function findEarliestSafeCompletionTime() {
    // Define the work packages and their durations
    const workPackages = [
        { name: 'A', duration: 5 },
        { name: 'B', duration: 6 },
        { name: 'C', duration: 5 },
        { name: 'D', duration: 9 },
        { name: 'E', duration: 7 }
    ];

    // Sort the work packages by their duration in ascending order
    workPackages.sort((a, b) => a.duration - b.duration);

    // Initialize variables to track the earliest safe completion time and the remaining time
    let earliestSafeCompletionTime = Infinity;
    let remainingTime = 44;

    // Iterate through the sorted work packages
    for (const package of workPackages) {
        // Check if the current package can start after A but may run in parallel
        if (package.name === 'A' && package.duration <= remainingTime) {
            // Update the earliest safe completion time if this package is faster
            earliestSafeCompletionTime = Math.min(earliestSafeCompletionTime, package.duration);
            remainingTime -= package.duration;
        }
    }

    // Check if the remaining time is less than 5 minutes and meets the safety or review buffer limit
    if (remainingTime < 5 && earliestSafeCompletionTime <= 44) {
        return `The earliest safe completion time is ${earliestSafeCompletionTime} minutes, and the plan meets the limit.`;
    } else {
        return `The earliest safe completion time is ${earliestSafeCompletionTime} minutes, but the plan does not meet the limit.`;
    }
}

