    const timeA = 13;
    const timeB = 16;
    const timeC = 11;
    const timeD = 5;
    const timeE = 7;

    // Calculate the total time required for all packages combined
    const totalCombinedTime = timeA + timeB + timeC + timeD + timeE;

    // Calculate the earliest safe completion time
    const earliestSafeCompletionTime = totalTime - totalCombinedTime;

    // Check if the plan meets the limit
    if (earliestSafeCompletionTime <= 42) {
        return `The earliest safe completion time is ${earliestSafeCompletionTime} minutes, and the plan meets the limit.`;
