function calculateMeanAndDirection(data, mean) {
    const sum = data.reduce((acc, curr) => acc + curr, 0);
    const count = data.length;
    const newMean = (sum / count) + mean;

    if (newMean > mean) {
        return "The new mean is greater than the original mean. The data is increasing.";
    } else if (newMean < mean) {
        return "The new mean is less than the original mean. The data is decreasing.";
    } else {
        return "The new mean is equal to the original mean. The data is stable.";
    }
}

