function minStepsToLibrary(target, library) {
  // Calculate the Manhattan distance from the start to the library
  const manhattanDistance = Math.abs(library[0] - target[0]) + Math.abs(library[1] - target[1]);

  // Calculate the Manhattan distance from the library to the target
  const targetToLibraryDistance = Math.abs(target[0] - library[0]) + Math.abs(target[1] - library[1]);

  // The minimum number of steps is the sum of the Manhattan distances
  return manhattanDistance + targetToLibraryDistance;
}

