```javascript
function findPath(graph, start, end) {
    const visited = new Set();
    const queue = [start];
    let path = [];

    while (queue.length > 0) {
        const current = queue.shift();

        if (current === end) {
            return path;
        }

        if (!visited.has(current)) {
            visited.add(current);
            for (const neighbor of graph[current]) {
                if (!visited.has(neighbor)) {
                    queue.push(neighbor);
                    path.push(neighbor);
                }
            }
        }
    }

    return null;
}

const graph = [
    [31, 35, 6, 29],
    [4]
];

console.log(findPath(graph, 31, 29)); // Output: [31, 35, 6, 29]
```

