function findMinimalWinningCoalitions(seats) {
  // Check if there are at least 6 seats required for a coalition to win
  if (seats < 6) {
    return "No minimal winning coalitions possible";
  }

  // Iterate through all possible combinations of groups
  const minWinningCoalitions = [];
  for (let i = 1; i <= seats; i++) {
    for (let j = 1; j <= seats - i; j++) {
      for (let k = 1; k <= seats - i - j; k++) {
        if (i + j + k === seats) {
          minWinningCoalitions.push(`Coalition with ${i} seats, ${j} seats, ${k} seats`);
        }
      }
    }
  }

  // Return the minimal winning coalitions as a string
  return minWinningCoalitions.join(", ");
}

